// TypeScript Version: 4.1

import dlasq5 = require( './index' );

// TESTS //

// The function returns a Float64Array...
{
	const Z = new Float64Array( [ 5, 0, 7, 0, 9, 0, 3, 0, 11, 0, 4, 0, 20, 0, 0, 0 ] );
	const out = new Float64Array( 6 );

	dlasq5( 0, 3, Z, false, 0.1, 0.0, true, 2.220446049250313e-16, out ); // $ExpectType Float64Array
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const Z = new Float64Array( 16 );
	const out = new Float64Array( 6 );

	dlasq5( '5', 3, Z, false, 0.1, 0.0, true, 2.220446049250313e-16, out ); // $ExpectError
	dlasq5( true, 3, Z, false, 0.1, 0.0, true, 2.220446049250313e-16, out ); // $ExpectError
	dlasq5( false, 3, Z, false, 0.1, 0.0, true, 2.220446049250313e-16, out ); // $ExpectError
	dlasq5( null, 3, Z, false, 0.1, 0.0, true, 2.220446049250313e-16, out ); // $ExpectError
	dlasq5( undefined, 3, Z, false, 0.1, 0.0, true, 2.220446049250313e-16, out ); // $ExpectError
	dlasq5( [], 3, Z, false, 0.1, 0.0, true, 2.220446049250313e-16, out ); // $ExpectError
	dlasq5( {}, 3, Z, false, 0.1, 0.0, true, 2.220446049250313e-16, out ); // $ExpectError
	dlasq5( ( x: number ): number => x, 3, Z, false, 0.1, 0.0, true, 2.220446049250313e-16, out ); // $ExpectError
}

